from django.core.management.base import BaseCommand
from django.db import transaction
from docs.models import Author, Project, Document, Version

class Command(BaseCommand):
    help = 'Создать демонстрационные данные без повторов и без перезаписи существующих записей'
    @transaction.atomic
    def handle(self, *args, **options):
        author, _ = Author.objects.get_or_create(email='arseniy@example.com', defaults={'full_name': 'Васильев Арсений Витальевич'})
        editor, _ = Author.objects.get_or_create(email='editor@example.com', defaults={'full_name': 'Редактор документации (пример)'})
        data = [
            ('techdocs', 'Платформа ТехДок', 'Руководства по настройке, публикации и сопровождению системы технической документации.', [
                ('quickstart', 'Быстрый старт', 'Первый запуск системы и знакомство с интерфейсом.', [
                    ('1.0', 'Первая публикация', 'Назначение системы\nТехДок хранит документацию по проектам и позволяет читать опубликованные версии.\n\nНачало работы\n1. Откройте каталог проектов.\n2. Выберите проект.\n3. Откройте нужный документ.', 'published'),
                    ('1.1', 'Добавлен порядок запуска и работы с версиями', 'Назначение системы\nТехДок объединяет технические документы, их авторов и историю публикаций.\n\nЛокальный запуск\n1. Установите зависимости из requirements.txt.\n2. Выполните python manage.py migrate.\n3. Выполните python manage.py seed_demo.\n4. Запустите python manage.py runserver.\n\nЧтение документации\nВыберите проект в каталоге и откройте документ. По умолчанию показывается последняя опубликованная версия. Предыдущие публикации доступны в блоке «История версий».\n\nВнесение изменений\nРедактор входит в админ-панель и создаёт новую версию. Черновик не отображается читателям. После проверки редактор устанавливает статус «Опубликована».', 'published'),
                    ('1.2', 'Подготовка расширенного руководства', 'Этот текст находится на проверке и не должен попадать в публичный каталог.', 'draft')]),
                ('publishing', 'Регламент публикации', 'Как подготовить документ и выпустить новую версию.', [
                    ('1.0', 'Утверждён регламент', 'Подготовка\nСоздайте автора, проект и карточку документа в админ-панели.\n\nПроверка\nСоздайте версию со статусом «Черновик». Укажите номер, автора, описание изменений и содержимое. Проверьте корректность инструкции.\n\nПубликация\nПереключите статус на «Опубликована» и сохраните. Дата публикации устанавливается автоматически.\n\nИсправления\nОпубликованная версия доступна только для чтения. Для исправлений создайте новую версию с другим номером. Авторов и документы, на которые ссылаются версии, нельзя удалить.', 'published')])]),
            ('integration', 'Интеграционный модуль', 'Описание форматов обмена и порядок подключения к учебному интеграционному модулю.', [
                ('format', 'Формат обмена данными', 'Структура сообщения и правила проверки обязательных полей.', [
                    ('1.0', 'Описана структура сообщения', 'Назначение\nДокумент описывает проектируемый учебный формат обмена; это спецификация, а не реализованный API системы ТехДок.\n\nПоля сообщения\nproject — код проекта.\ndocument — код документа.\nversion — номер версии.\nauthor — имя автора.\ncontent — текст документа.\n\nПроверка данных\nОбязательные поля не должны быть пустыми. Номер версии должен быть уникальным в пределах документа. Текст передаётся в кодировке UTF-8.', 'published')])])]
        for slug, title, description, documents in data:
            project, _ = Project.objects.get_or_create(slug=slug, defaults={'title': title, 'description': description})
            for doc_slug, doc_title, summary, versions in documents:
                document, _ = Document.objects.get_or_create(project=project, slug=doc_slug, defaults={'title': doc_title, 'summary': summary})
                for number, note, content, status in versions:
                    Version.objects.get_or_create(document=document, number=number, defaults={
                        'author': author if slug == 'techdocs' else editor, 'content': content,
                        'change_note': note, 'status': status})
        self.stdout.write(self.style.SUCCESS('Демонстрационные данные готовы.'))
